fun main() {
    val l = mutableListOf(5, 3, 8, 1)
    l.sort()
    println(l)
    l.add(1, 99)
    l.removeAt(0)
    l.remove(8)
    println(l)
    l.addAll(listOf(7, 7))
    l.removeAll { it == 7 }
    println(l)
    l.reverse()
    println(l)
    l.shuffle(kotlin.random.Random(1))
    println(l.sorted())
    val m = mutableMapOf("a" to 1)
    m.getOrPut("b") { 2 }
    m.merge("a", 10) { o, n -> o + n }
    m.compute("c") { _, v -> (v ?: 0) + 5 }
    println(m)
    m.putIfAbsent("a", 0)
    println(m.getOrDefault("z", -1))
    println(m.filterValues { it > 3 })
    println(m.mapValues { it.value * 2 })
    println(m.mapKeys { it.key.uppercase() })
    println(m.toList())
    println(m.entries.sortedByDescending { it.value }.map { it.key })
    println(m.maxByOrNull { it.value }?.key)
    println(m.remove("a"))
    println(m + ("q" to 0) - "b")
    val s = mutableSetOf(1, 2, 3)
    println(s.add(2) to s.add(4))
    println(s intersect setOf(2, 4, 9))
    println(s union setOf(9))
    println(s subtract setOf(1))
    println(setOf(1, 2) == setOf(2, 1))
    val arr = arrayOf(3, 1, 2)
    arr.sort()
    println(arr.toList() to arr.reversed())
    val ia = IntArray(5) { it * it }
    println(ia.sum() to ia.max() to ia.indexOf(9))
    println(ia.copyOfRange(1, 3).toList())
    println(Array(2) { r -> IntArray(2) { c -> r + c } }.map { it.toList() })
    println(listOf(1, 2, 3).reversed() + listOf(4).asReversed())
    println(List(3) { "x$it" })
    println(listOf(1, 2, 3, 4, 5).subList(1, 4))
    println(listOf(3, 1, 2).sortedDescending().first())
    println(listOf("a", "b").withIndex().map { (i, v) -> "$i$v" })
    println((1..4).reduce { a, b -> a * b })
    println(listOf(1, null, 2).filterNotNull().sum())
    println(listOf(1, 2, 3).sumOf { it * 1.5 })
    println(ArrayDeque(listOf(1, 2)).also { it.addFirst(0); it.addLast(3) })
    println(listOf(1, 2, 3, 4).filterIndexed { i, _ -> i % 2 == 0 })
    println(listOf("x", "y").mapIndexed { i, s -> s.repeat(i + 1) })
    println(emptyList<Int>().maxOrNull() to emptyList<Int>().sum())
    println(listOf(1, 2, 3).random(kotlin.random.Random(5)) in 1..3)
    println(listOf(4, 5, 6).lastIndex)
    println(listOf(1, 2, 3).contains(2) && 4 !in listOf(1))
}
